issue_context.body:
Calling Convert with a given char[], i.e.:  { '1', '2', '\uD804', '3', '4' } in a unique call gives different results than when calling Convert for each independent character in a loop. This only happens with some .NET versions.

Tested with .Net Framework 4.6.1 and .Net Core 2.0.3 with correct results
.Net Core 3.1.2 returned different results

```csharp
using System;
using System.IO;
using System.Text;

namespace Test
{
    class Program
    {
        static void Main(string[] args)
        {
            Encoder encoder = Encoding.UTF8.GetEncoder();
            encoder.Fallback = EncoderFallback.ReplacementFallback;

            var data = new[] { '1', '2', '\uD804', '3', '4' };

            var bytes = new byte[10];

            encoder.Convert(data, 0, data.Length, bytes, 0, bytes.Length, false, out _, out var byteCount, out _);

            for (var i = 0; i < byteCount; i++) 
                Console.Write(bytes[i].ToString("x") + " "); // Returns 31 32 3f 33 34 in netcore and framework

            Console.WriteLine();

            encoder = Encoding.UTF8.GetEncoder();
            encoder.Fallback = EncoderFallback.ReplacementFallback;

            foreach (var c in data)
            {
                encoder.Convert(new[] { c }, 0, 1, bytes, 0, bytes.Length, false, out var charCount, out byteCount, out _);

                if (charCount >= 1)
                    for (int i = 0; i < byteCount; i++)
                        Console.Write(bytes[i].ToString("x") + " ");

                        // Returns 31 32 3f 33 34    in framework 4.6.1
                        // Returns 31 32 3f 33 3f 34 in netcore 3.1.2
            }
        }
    }
}
```
